    "C01", "C08", "C13", "C02", "C06", "C07", "C12", "C43", "C35", "C40"
  ],
  "claims": [
    {
      "claim": "Transferable L1 gold-context records in fasted/non-cirrhotic oral settings report absolute F values well above 20%: melperone 54–67%, vernakalant 58–71%, suvorexant 82%, propylthiouracil 77%, BI 425809 71.6%, levofloxacin ~100%, and hyperforin reported as high.",
      "card_ids": ["C01", "C05", "C14", "C08", "C11", "C13", "C02", "C06", "C07", "C12"]
    },
    {
      "claim": "L4 records show high intestinal absorption or permeability for structurally similar lipophilic, chloro-substituted, basic/thiourea-containing molecules: desloratadine F_abs >90%, domperidone virtually complete absorption, UC-781 BCS II high permeability, lorcaserin high permeability and not a P-gp substrate, loratadine BCS II high permeability, indapamide 100% absorption, and difenoconazole high Papp.",
      "card_ids": ["C33", "C40", "C43", "C35", "C41", "C42", "C44", "C38"]
    },
    {
      "claim": "L4 also notes low aqueous solubility for some BCS II compounds (UC-781, loratadine, γ-T3), but BCS II classification and solubility limitation alone do not affirm F <20%; no transferable record provides a low absolute F for the query.",
      "card_ids": ["C43", "C42", "C36"]
    },
    {
      "claim": "No direct query-specific absolute F or matched oral-IV exposure is available; L3 Cmax and L4 permeability/absorption evidence support the absorption component but do not quantify systemic F, so confidence is moderate at most.",
      "card_ids": ["C21", "C25", "C33", "C40", "C43"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C33", "C34", "C35", "C38", "C40", "C41", "C42", "C43", "C44"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability or matched oral-versus-IV exposure measurement is available.",
    "No query-specific aqueous solubility or dissolution data; high logP/logD and BCS II-like reference records indicate a possible solubility limitation.",
    "No query-specific first-pass, metabolic stability, or efflux data; thiourea and prenyl/alkene groups are potential metabolic liabilities.",
    "L4 records are for reference molecules, not the query; transfer is qualitative and assay/formulation context differs.",
    "No affirmative low-F evidence from a transferable context is present."
  ],
  "decision_summary": "Predicted high (F >= 20%) with moderate confidence. L1 gold-context records uniformly report F >20% in fasted/non-cirrhotic oral settings, and L4 adds human absorption/Caco-2 permeability evidence for structurally similar lipophilic chloro/basic/thiourea compounds, supporting the absorption component. Solubility limitations are noted but do not affirm F <20%, and no transferable low-F evidence is present; therefore the prior high prediction is strengthened."
}

